/**
 * 一次完整分析帧（v4 新增）：feed 事件 + 频谱 + 泛音 + 和弦。
 */
public struct AnalysisFrame {
    /**
     * 同 feed 语义（无效输入为 None）。
     */
    public var tuner: TunerEvent?
    /**
     * 64 bin 对数轴 60–2400Hz 幅值（dBFS -80~0）。
     */
    public var spectrumDb: [Float]
    /**
     * 128 bin 对数轴 20Hz–wide_spectrum_max_hz 幅值（dBFS -80~0）。
     */
    public var wideSpectrumDb: [Float]
    /**
     * 全频段实际频率上限（min(20kHz, sample_rate/2)）。
     */
    public var wideSpectrumMaxHz: Double
    /**
     * 当前分析窗口 256 列最小值包络。
     */
    public var waveformMin: [Float]
    /**
     * 当前分析窗口 256 列最大值包络。
     */
    public var waveformMax: [Float]
    /**
     * 当前帧末端相对引擎启动时的采样位置。
     */
    public var samplePosition: UInt64
    /**
     * 实际分析采样率。
     */
    public var sampleRateHz: Double
    /**
     * 泛音列（≤8，按幅值降序）。
     */
    public var partials: [Partial]
    /**
     * 和弦名（如 "Cmaj"），无则为 None。
     */
    public var chord: String?
    /**
     * 输入信号状态。
     */
    public var signalState: SignalState
    /**
     * 当前分析窗口的 RMS 电平（dBFS）。
     */
    public var inputLevelDbfs: Float
    /**
     * 读数显示强度（0~1）。
     */
    public var displayStrength: Float
    /**
     * 当前读数是否来自断音保持。
     */
    public var isHeld: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 同 feed 语义（无效输入为 None）。
         */tuner: TunerEvent?, 
        /**
         * 64 bin 对数轴 60–2400Hz 幅值（dBFS -80~0）。
         */spectrumDb: [Float], 
        /**
         * 128 bin 对数轴 20Hz–wide_spectrum_max_hz 幅值（dBFS -80~0）。
         */wideSpectrumDb: [Float], 
        /**
         * 全频段实际频率上限（min(20kHz, sample_rate/2)）。
         */wideSpectrumMaxHz: Double, 
        /**
         * 当前分析窗口 256 列最小值包络。
         */waveformMin: [Float], 
        /**
         * 当前分析窗口 256 列最大值包络。
         */waveformMax: [Float], 
        /**
         * 当前帧末端相对引擎启动时的采样位置。
         */samplePosition: UInt64, 
        /**
         * 实际分析采样率。
         */sampleRateHz: Double, 
        /**
         * 泛音列（≤8，按幅值降序）。
         */partials: [Partial], 
        /**
         * 和弦名（如 "Cmaj"），无则为 None。
         */chord: String?, 
        /**
         * 输入信号状态。
         */signalState: SignalState, 
        /**
         * 当前分析窗口的 RMS 电平（dBFS）。
         */inputLevelDbfs: Float, 
        /**
         * 读数显示强度（0~1）。
         */displayStrength: Float, 
        /**
         * 当前读数是否来自断音保持。
         */isHeld: Bool) {
        self.tuner = tuner
        self.spectrumDb = spectrumDb
        self.wideSpectrumDb = wideSpectrumDb
        self.wideSpectrumMaxHz = wideSpectrumMaxHz
        self.waveformMin = waveformMin
        self.waveformMax = waveformMax
        self.samplePosition = samplePosition
        self.sampleRateHz = sampleRateHz
        self.partials = partials
        self.chord = chord
        self.signalState = signalState
        self.inputLevelDbfs = inputLevelDbfs
        self.displayStrength = displayStrength
        self.isHeld = isHeld
    }
}

