extension AnalysisFrame: Sendable {}
#endif


extension AnalysisFrame: Equatable, Hashable {
    public static func ==(lhs: AnalysisFrame, rhs: AnalysisFrame) -> Bool {
        if lhs.tuner != rhs.tuner {
            return false
        }
        if lhs.spectrumDb != rhs.spectrumDb {
            return false
        }
        if lhs.wideSpectrumDb != rhs.wideSpectrumDb {
            return false
        }
        if lhs.wideSpectrumMaxHz != rhs.wideSpectrumMaxHz {
            return false
        }
        if lhs.waveformMin != rhs.waveformMin {
            return false
        }
        if lhs.waveformMax != rhs.waveformMax {
            return false
        }
        if lhs.samplePosition != rhs.samplePosition {
            return false
        }
        if lhs.sampleRateHz != rhs.sampleRateHz {
            return false
        }
        if lhs.partials != rhs.partials {
            return false
        }
        if lhs.chord != rhs.chord {
            return false
        }
        if lhs.signalState != rhs.signalState {
            return false
        }
        if lhs.inputLevelDbfs != rhs.inputLevelDbfs {
            return false
        }
        if lhs.displayStrength != rhs.displayStrength {
            return false
        }
        if lhs.isHeld != rhs.isHeld {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(tuner)
        hasher.combine(spectrumDb)
        hasher.combine(wideSpectrumDb)
        hasher.combine(wideSpectrumMaxHz)
        hasher.combine(waveformMin)
        hasher.combine(waveformMax)
        hasher.combine(samplePosition)
        hasher.combine(sampleRateHz)
        hasher.combine(partials)
        hasher.combine(chord)
        hasher.combine(signalState)
        hasher.combine(inputLevelDbfs)
        hasher.combine(displayStrength)
        hasher.combine(isHeld)
    }
}



